CREATE TABLE IF NOT EXISTS medicines (
  id TEXT PRIMARY KEY,
  name TEXT NOT NULL,
  nepali_name TEXT NOT NULL,
  category TEXT NOT NULL,
  forms TEXT NOT NULL DEFAULT '',
  use_description TEXT NOT NULL,
  symptoms TEXT NOT NULL DEFAULT '',
  caution TEXT NOT NULL,
  side_effects TEXT NOT NULL DEFAULT '',
  prescription_status TEXT NOT NULL DEFAULT 'फार्मासिस्टसँग पुष्टि गर्नुहोस्',
  price_npr NUMERIC(10,2),
  price_note TEXT NOT NULL DEFAULT 'मूल्य पुष्टि हुन बाँकी',
  source TEXT NOT NULL,
  price_verified BOOLEAN NOT NULL DEFAULT FALSE,
  price_updated_at TIMESTAMPTZ,
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  CONSTRAINT medicine_price_nonnegative CHECK (price_npr IS NULL OR price_npr >= 0)
);
CREATE INDEX IF NOT EXISTS medicines_category_idx ON medicines(category);
CREATE INDEX IF NOT EXISTS medicines_name_idx ON medicines USING gin (to_tsvector('simple', name || ' ' || nepali_name || ' ' || category));
INSERT INTO medicines(id,name,nepali_name,category,forms,use_description,symptoms,caution,side_effects,prescription_status,price_npr,price_note,source,price_verified)
VALUES
('paracetamol','Paracetamol','प्यारासिटामोल','दुखाइ तथा ज्वरो','ट्याब्लेट, सिरप, ड्रप','ज्वरो घटाउन र हल्का देखि मध्यम दुखाइ कम गर्न प्रयोग गरिन्छ।','टाउको दुखाइ, दाँत दुखाइ, शरीर दुखाइ र ज्वरो','कलेजोसम्बन्धी समस्या, नियमित मदिरा सेवन वा अन्य paracetamol भएको औषधि प्रयोग गरिरहनुभएको छ भने चिकित्सक/फार्मासिस्टसँग सल्लाह लिनुहोस्। मात्रा आफैं नबढाउनुहोस्।','दुर्लभ रूपमा एलर्जी वा कलेजोमा गम्भीर असर हुन सक्छ।','उत्पादन र formulation अनुसार फरक पर्न सक्छ',NULL,'फार्मेसीबाट मूल्य पुष्टि हुन बाँकी','सामान्य औषधि जानकारी; ब्रान्ड/प्याकेटअनुसार पुष्टि गर्नुपर्ने',FALSE),
('cetirizine','Cetirizine','सेटिरिजिन','एलर्जी','ट्याब्लेट, सिरप','एलर्जीका लक्षण कम गर्न प्रयोग हुने antihistamine औषधि हो।','छिँक आउने, नाक/आँखा चिलाउने, पानी बग्ने र छालामा चिलाउने डाबर','निद्रा लाग्न सक्छ। गाडी चलाउँदा सावधानी अपनाउनुहोस्। गर्भावस्था, स्तनपान, मिर्गौलाको समस्या वा बालबालिकामा प्रयोगअघि स्वास्थ्यकर्मीसँग सल्लाह लिनुहोस्।','निद्रा लाग्ने, मुख सुक्ने, थकान वा टाउको दुख्ने','उत्पादनको लेबल/फार्मासिस्टबाट पुष्टि गर्नुहोस्',NULL,'फार्मेसीबाट मूल्य पुष्टि हुन बाँकी','सामान्य औषधि जानकारी; उत्पादन-विशेष विवरण पुष्टि गर्नुपर्ने',FALSE),
('ibuprofen','Ibuprofen','आइबुप्रोफेन','दुखाइ तथा सुन्निने समस्या','ट्याब्लेट, सस्पेन्सन','दुखाइ, ज्वरो र सूजन कम गर्न प्रयोग हुने NSAID औषधि हो।','मांसपेशी/जोर्नी दुखाइ, महिनावारी दुखाइ र केही प्रकारका सूजन','पेटको अल्सर/रक्तस्राव, मिर्गौला वा मुटुको समस्या, गर्भावस्थाको विशेष अवस्था वा रगत पातलो बनाउने औषधि प्रयोगमा जोखिम हुन सक्छ। चिकित्सकको सल्लाहबिना नलिनुहोस्।','पेट दुख्ने, अपच, वाकवाकी; गम्भीर अवस्थामा पेटबाट रक्तस्राव वा मिर्गौलामा असर','उत्पादन र शक्तिअनुसार फरक पर्न सक्छ',NULL,'फार्मेसीबाट मूल्य पुष्टि हुन बाँकी','सामान्य औषधि जानकारी; उत्पादन-विशेष विवरण पुष्टि गर्नुपर्ने',FALSE),
('ors','Oral Rehydration Salts (ORS)','जीवनजल (ओआरएस)','पानी तथा लवणको कमी','पाउडर स्याचेट','पखाला वा बान्ताका कारण शरीरबाट गएको पानी र लवण पूर्ति गर्न मद्दत गर्छ।','पखाला/बान्तापछि हुने निर्जलीकरण रोकथाम तथा उपचारमा सहयोग','स्याचेटमा लेखिएको पानीको ठ्याक्कै मात्रामा मात्र घोल्नुहोस्। थप चिनी/नुन नमिसाउनुहोस्। गम्भीर निर्जलीकरण वा पिउन नसक्ने अवस्था भए तुरुन्त स्वास्थ्य संस्था जानुहोस्।','गलत अनुपातमा तयार गर्दा समस्या बढ्न सक्छ।','सामान्यतया prescription नचाहिने; प्याकेटको निर्देशन पालना गर्नुहोस्',NULL,'फार्मेसीबाट मूल्य पुष्टि हुन बाँकी','सामान्य स्वास्थ्य जानकारी; प्याकेटको निर्देशन प्राथमिक',FALSE),
('omeprazole','Omeprazole','ओमेप्राजोल','पेटको अम्ल','क्याप्सुल, ट्याब्लेट','पेटमा बन्ने अम्ल घटाउने औषधि (proton pump inhibitor) हो।','अम्लपित्त/GERD, पेट वा आन्द्राको केही अल्सरमा चिकित्सकले सिफारिस गर्न सक्छन्।','लामो समय आफैं प्रयोग नगर्नुहोस्। निल्न गाह्रो, रगत बान्ता, कालो दिसा वा अनायास तौल घटेमा तुरुन्त जाँच गराउनुहोस्।','टाउको दुख्ने, पेट दुख्ने, वाकवाकी, पखाला वा कब्जियत','निदान र उत्पादनअनुसार स्वास्थ्यकर्मीको सल्लाह आवश्यक हुन सक्छ',NULL,'फार्मेसीबाट मूल्य पुष्टि हुन बाँकी','सामान्य औषधि जानकारी; उत्पादन-विशेष विवरण पुष्टि गर्नुपर्ने',FALSE),
('amoxicillin','Amoxicillin','एमोक्सिसिलिन','एन्टिबायोटिक','क्याप्सुल, ट्याब्लेट, सस्पेन्सन','केही ब्याक्टेरियाबाट हुने संक्रमणको उपचारमा चिकित्सकले प्रयोग गराउने penicillin समूहको एन्टिबायोटिक हो।','कान, छाती, घाँटी वा अन्य ब्याक्टेरियल संक्रमण—संक्रमणको प्रकारअनुसार चिकित्सकले निर्णय गर्छन्।','भाइरसका कारण हुने रुघाखोकी/फ्लुमा काम गर्दैन। बाँकी औषधि आफैं नखानुहोस्, अरूलाई नदिनुहोस्। Penicillin allergy भए प्रयोग नगर्नुहोस् र स्वास्थ्यकर्मीलाई जानकारी दिनुहोस्।','पखाला, वाकवाकी, छालामा डाबर; सास फेर्न गाह्रो/अनुहार सुन्निएमा आपतकालीन उपचार लिनुहोस्।','प्रिस्क्रिप्सन आवश्यक',NULL,'फार्मेसीबाट मूल्य पुष्टि हुन बाँकी','सामान्य औषधि जानकारी; एन्टिबायोटिकको प्रयोग चिकित्सकको निर्णयमा',FALSE)
ON CONFLICT(id) DO NOTHING;
